use super::*;use quantum_ecc::sim::Simulator;
struct Fixed(u8);impl sha3::digest::XofReader for Fixed{fn read(&mut self,out:&mut[u8]){out.fill(self.0);}}
fn algebra()->Algebra{Algebra{next:1,cap:256,degree:12,cuts:0}}
fn gate(k:K,a:u64,b:u64,t:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_control1=QubitId(a);o.q_control2=QubitId(b);o.q_target=QubitId(t);o}
fn fixture()->Vec<Op>{(0..3).map(|t|{let mut o=gate(K::AppendToRegister,NO,NO,t);o.r_target.0=0;o}).collect()}
fn hmr(q:u64)->Op{let mut o=gate(K::Hmr,NO,NO,q);o.c_target.0=0;o}
fn dimensions(v:&[Op])->usize{v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&x|x!=NO).max().unwrap()as usize+1}
fn paired(v:&[Op],out:&[Op]){assert_eq!(dimensions(v),dimensions(out));assert_eq!(v.iter().filter(|x|matches!(x.kind,K::R|K::Hmr)).collect::<Vec<_>>(),out.iter().filter(|x|matches!(x.kind,K::R|K::Hmr)).collect::<Vec<_>>());for pattern in [0,255,0xa5,0x5a]{for input in 0..8{let mut ra=Fixed(pattern);let mut rb=Fixed(pattern);let mut a=Simulator::new(8,2,&mut ra);let mut b=Simulator::new(8,2,&mut rb);a.phase=0xa55a;for i in 0..3{a.qubits[i]=(input>>i)&1;}b.qubits.clone_from(&a.qubits);b.phase=a.phase;a.apply_iter(v.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);}}}
fn optimized(v:&[Op])->(Vec<Op>,Vec<serde_json::Value>){scan_copy(v,&mut algebra())}
#[test]fn capture_arbitrary_target_and_consume_clean_target_with_same_rng(){for dirty_first in [false,true]{let mut v=fixture();if dirty_first{v.push(gate(K::X,NO,NO,3));}v.extend([gate(K::CCX,0,1,3),hmr(3),gate(K::CCX,0,1,3),gate(K::R,NO,NO,7)]);let(out,s)=optimized(&v);assert_eq!(s.len(),1);assert_eq!(s[0]["storage"],4);assert_eq!(out.iter().filter(|x|x.kind==K::CCX).count(),1);paired(&v,&out);}}
#[test]fn algebraically_equal_products_on_different_control_wires_cache_exactly(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),hmr(3),gate(K::CX,0,NO,4),gate(K::X,NO,NO,4),gate(K::CX,1,NO,4),gate(K::CCX,0,4,3),gate(K::R,NO,NO,5)]);let(out,s)=optimized(&v);assert_eq!(s.len(),1);assert_eq!(s[0]["storage"],5);paired(&v,&out);}
#[test]fn no_existing_idle_wire_means_no_change(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),hmr(3),gate(K::CCX,0,1,3)]);let(out,s)=optimized(&v);assert!(s.is_empty());assert_eq!(out,v);paired(&v,&out);}
#[test]fn even_a_phase_only_touch_prevents_storage_use(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::Z,NO,NO,4),hmr(3),gate(K::CCX,0,1,3)]);let(out,s)=optimized(&v);assert!(s.is_empty());assert_eq!(out,v);paired(&v,&out);}
#[test]fn nonzero_consuming_target_is_refused(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),hmr(3),gate(K::X,NO,NO,3),gate(K::CCX,0,1,3),gate(K::R,NO,NO,7)]);let(out,s)=optimized(&v);assert!(s.is_empty());assert_eq!(out,v);paired(&v,&out);}
#[test]fn overlapping_cache_intervals_cannot_share_the_only_idle_slot(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),gate(K::CCX,0,2,4),hmr(3),hmr(4),gate(K::CCX,0,1,3),gate(K::CCX,0,2,4),gate(K::R,NO,NO,5)]);let(out,s)=optimized(&v);assert_eq!(s.len(),1);assert_eq!(s[0]["storage"],5);paired(&v,&out);}
#[test]fn conditional_consumption_is_not_cached(){let mut v=fixture();v.extend([gate(K::CCX,0,1,3),hmr(3)]);let mut push=Op::empty();push.kind=K::PushCondition;push.c_condition.0=0;let mut pop=Op::empty();pop.kind=K::PopCondition;v.extend([push,gate(K::CCX,0,1,3),pop,gate(K::R,NO,NO,7)]);let(out,s)=optimized(&v);assert!(s.is_empty());assert_eq!(out,v);paired(&v,&out);}
#[test]fn zeroed_abi_wire_is_never_used_for_storage(){let mut v=fixture();let mut ann=gate(K::AppendToRegister,NO,NO,4);ann.r_target.0=0;v.extend([ann,gate(K::R,NO,NO,4),gate(K::CCX,0,1,3),hmr(3),gate(K::CCX,0,1,3)]);let(out,s)=optimized(&v);assert!(s.is_empty());assert_eq!(out,v);paired(&v,&out);}
